import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom fused kernel for elementwise multiplication and LeakyReLU
fused_kernel_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_mult_leaky_relu_kernel(
    const float* input,
    float multiplier,
    float negative_slope,
    float* output,
    int num_elements
) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float val = input[idx] * multiplier;
        output[idx] = val > 0 ? val : val * negative_slope;
    }
}

torch::Tensor fused_op_cuda(
    torch::Tensor input,
    float multiplier,
    float negative_slope
) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();
    int threads = 256;
    int blocks = (num_elements + threads - 1) / threads;

    fused_mult_leaky_relu_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        multiplier,
        negative_slope,
        output.data_ptr<float>(),
        num_elements
    );

    return output;
}
"""

cpp_code = "torch::Tensor fused_op_cuda(torch::Tensor input, float multiplier, float negative_slope);"

fused_op = load_inline(
    name='fused_op',
    cpp_sources=cpp_code,
    cuda_sources=fused_kernel_code,
    functions=['fused_op_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, multiplier, negative_slope):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features)
        self.multiplier = multiplier
        self.negative_slope = negative_slope

    def forward(self, x):
        x = self.gemm(x)
        x = fused_op.fused_op_cuda(x, self.multiplier, self.negative_slope)
        return x
